export const samplerDefaults={wrapS:'repeat',wrapT:'repeat',wrapR:'repeat',minFilter:'linear',magFilter:'linear',mipmaps:true};
export function validSamplerState(value){return value===undefined||value&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).every(k=>Object.hasOwn(samplerDefaults,k))&&['wrapS','wrapT','wrapR'].every(k=>value[k]===undefined||['repeat','clamp','mirror'].includes(value[k]))&&['minFilter','magFilter'].every(k=>value[k]===undefined||['linear','nearest'].includes(value[k]))&&(value.mipmaps===undefined||typeof value.mipmaps==='boolean');}
export function applySamplerState(THREE,map,value={},fallback='repeat'){if(!validSamplerState(value))throw Error('텍스처 샘플러 상태 오류');const p={...samplerDefaults,wrapS:fallback,wrapT:fallback,wrapR:fallback,...value},wrap={repeat:THREE.RepeatWrapping,clamp:THREE.ClampToEdgeWrapping,mirror:THREE.MirroredRepeatWrapping};for(const k of ['wrapS','wrapT','wrapR'])map[k]=wrap[p[k]];map.generateMipmaps=p.mipmaps;map.magFilter=p.magFilter==='nearest'?THREE.NearestFilter:THREE.LinearFilter;map.minFilter=p.mipmaps?(p.minFilter==='nearest'?THREE.NearestMipmapNearestFilter:THREE.LinearMipmapLinearFilter):(p.minFilter==='nearest'?THREE.NearestFilter:THREE.LinearFilter);map.needsUpdate=true;return map;}
